<?php extract($document,EXTR_SKIP);$e=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$n=static fn($v)=>decimalDisplay((string)$v); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><style>
@page{margin:17mm}body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#192c38}h1{font-size:20px}h2{font-size:13px}p{margin:4px 0}.header{border-bottom:2px solid #14856e;padding-bottom:14px}.logo{max-width:110px;max-height:65px;float:right}.meta{margin:15px 0}.lines{width:100%;border-collapse:collapse;table-layout:fixed}.lines th,.lines td{padding:8px 5px;border-bottom:1px solid #d8e1e5;word-wrap:break-word;vertical-align:top}.lines th{background:#edf6f3;text-align:left}.lines .num{text-align:right}.lines th:first-child{width:42%}thead{display:table-header-group}tr{page-break-inside:avoid}.totals{text-align:right;margin-top:16px}.total{font-size:15px;font-weight:bold}.footer{border-top:1px solid #ddd;margin-top:28px;color:#52616c}
</style></head><body><header class="header"><?php if(!empty($company['logo_data'])&&in_array($company['logo_mime']??'',['image/png','image/jpeg'],true)&&(($company['logo_mime']??'')==='image/jpeg'||function_exists('imagecreatefromstring'))): ?><img class="logo" alt="" src="data:<?= $e($company['logo_mime']) ?>;base64,<?= base64_encode($company['logo_data']) ?>"><?php endif; ?><h2><?= $e($company['legal_name']?:$company['name']) ?></h2><?php foreach(['tax_id','address','phone','email'] as $key)if(!empty($company[$key])): ?><p><?= nl2br($e($company[$key])) ?></p><?php endif; ?><h1><?= $e($title) ?></h1><strong><?= $e($row['name'].' · '.$status) ?></strong></header>
<section class="meta"><h2><?= $kind==='purchase_orders'||($kind==='invoices'&&$row['invoice_type']==='supplier')?'Proveedor':'Contacto' ?>: <?= $e($contact['name']??'') ?></h2><?php foreach(['tax_id','address','phone','email'] as $key)if(!empty($contact[$key])): ?><p><?= nl2br($e($contact[$key])) ?></p><?php endif; ?><?php foreach(array_merge($meta,$references) as $label=>$value): ?><p><strong><?= $e($label) ?>:</strong> <?= $e($value) ?></p><?php endforeach; ?></section>
<table class="lines"><thead><tr><th>Descripción</th><th class="num">Cantidad</th><?php if(!$stock): ?><th class="num">Precio</th><th class="num">Importe</th><?php endif; ?></tr></thead><tbody><?php foreach($lines as $line): ?><tr><td><?= $e($line['product_name']) ?><?php foreach($line['tracking']??[] as $tracking): ?><br><?= $e($tracking['name']) ?> · <?= $n($tracking['quantity']) ?><?php endforeach; ?></td><td class="num"><?= $n($line['quantity']) ?></td><?php if(!$stock): ?><td class="num"><?= $n($line['unit_price']) ?></td><td class="num"><?= $n($line['total_amount']) ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table>
<?php if(!$stock): ?><div class="totals"><p>Base: <?= $n($row['base_amount']) ?> <?= $e($row['currency_code']) ?></p><?php foreach($taxes as $tax): ?><p><?= $e($tax['name']) ?>: <?= $n($tax['amount']) ?></p><?php endforeach; ?><p class="total">Total: <?= $n($row['total_amount']) ?> <?= $e($row['currency_code']) ?></p></div><?php endif; ?>
<?php if(!empty($row['notes'])||!empty($row['credit_reason'])): ?><p><?= nl2br($e($row['notes']??$row['credit_reason'])) ?></p><?php endif; ?><p class="footer">Konta · <?= $e($company['name'].' · '.$row['name']) ?></p></body></html>
